class Program {

  func bestDigits(_ number: String, _ numDigits: Int) -> String {
    var numDigits = numDigits
    var stack = [Character]()

    for digit in number {
      while numDigits > 0 && stack.count > 0 && digit > stack[stack.count - 1] {
        numDigits -= 1
        stack.removeLast()
      }

      stack.append(digit)
    }

    while numDigits > 0 {
      numDigits -= 1
      stack.removeLast()
    }

    return String(stack)
  }
}

